-- Multi-profils : profile.id devient auto-incrémenté, chaque donnée appartient à un profil.
-- Les données existantes (app mono-utilisateur) sont rattachées au profil n° 1.
ALTER TABLE "profile" ALTER COLUMN "id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "profile" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (sequence name "profile_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1);--> statement-breakpoint
ALTER TABLE "profile" ADD COLUMN "emoji" text DEFAULT '💪' NOT NULL;--> statement-breakpoint
-- Profil n° 1 créé s'il manque alors que des données existent (le profil n'était créé qu'au 1er enregistrement)
INSERT INTO "profile" ("id", "name")
SELECT 1, 'Moi'
WHERE NOT EXISTS (SELECT 1 FROM "profile" WHERE "id" = 1)
  AND (EXISTS (SELECT 1 FROM "workouts") OR EXISTS (SELECT 1 FROM "weights") OR EXISTS (SELECT 1 FROM "plans") OR EXISTS (SELECT 1 FROM "videos"));--> statement-breakpoint
UPDATE "profile" SET "name" = 'Moi' WHERE "name" = '';--> statement-breakpoint
-- Les id insérés explicitement n'avancent pas la séquence : on la recale après le max
SELECT setval(pg_get_serial_sequence('profile', 'id'), COALESCE((SELECT max("id") FROM "profile"), 0) + 1, false);--> statement-breakpoint
-- DEFAULT 1 temporaire : remplit les lignes existantes, puis retiré
ALTER TABLE "plans" ADD COLUMN "profile_id" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "plans" ALTER COLUMN "profile_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "videos" ADD COLUMN "profile_id" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "videos" ALTER COLUMN "profile_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "weights" ADD COLUMN "profile_id" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "weights" ALTER COLUMN "profile_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "workouts" ADD COLUMN "profile_id" integer DEFAULT 1 NOT NULL;--> statement-breakpoint
ALTER TABLE "workouts" ALTER COLUMN "profile_id" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "plans" ADD CONSTRAINT "plans_profile_id_profile_id_fk" FOREIGN KEY ("profile_id") REFERENCES "public"."profile"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "videos" ADD CONSTRAINT "videos_profile_id_profile_id_fk" FOREIGN KEY ("profile_id") REFERENCES "public"."profile"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "weights" ADD CONSTRAINT "weights_profile_id_profile_id_fk" FOREIGN KEY ("profile_id") REFERENCES "public"."profile"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "workouts" ADD CONSTRAINT "workouts_profile_id_profile_id_fk" FOREIGN KEY ("profile_id") REFERENCES "public"."profile"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "plans_profile_idx" ON "plans" USING btree ("profile_id");--> statement-breakpoint
CREATE INDEX "videos_profile_idx" ON "videos" USING btree ("profile_id");--> statement-breakpoint
CREATE INDEX "weights_profile_date_idx" ON "weights" USING btree ("profile_id","date");--> statement-breakpoint
CREATE INDEX "workouts_profile_date_idx" ON "workouts" USING btree ("profile_id","date");
